test("90 度回った Box の中の回っていないノードを画面上で左へ運ぶと、親の座標で y が運んだ量だけ増えた座標が書かれる", () => {
  // 運んだ量を親の向きへ戻さないと (3, 10) になる
  const onRepositionNode = vi.fn();
  renderCanvas({ selection: setupTurnedFrame(90), onRepositionNode });
  drawnTurnedFrame();

  dragNode("chip", { x: -7, y: 0 });

  expect(onRepositionNode).toHaveBeenCalledWith("chip", {
    parentName: "frame",
    placement: { mode: "absolute", x: 10, y: 17 },
  });
});

test("90 度回った Box の中のノードを運んでいる間、ずらして見せる量は親の向きへ戻した量になる", () => {
  // ずらし量は親と一緒に回って効くので、戻さないと画面上では上へずれて見える
  renderCanvas({ selection: setupTurnedFrame(90) });
  drawnTurnedFrame();

  carryNode("chip", { x: -7, y: 0 });

  expect(injectedStyles()).toContain(previewRule("chip", { x: 0, y: 7 }));
});

test("90 度回った Box の中のノードを落とせる親が無い場所へ運んでも、ずらして見せる量は親の向きへ戻した量になる", () => {
  renderCanvas({ selection: setupTurnedFrame(90) });
  drawnTurnedFrame();

  carryNode("chip", { x: -7, y: 0 });
  movePointer(artboardList(), { x: 93, y: 100 });

  expect(injectedStyles()).toContain(previewRule("chip", { x: 0, y: 7 }));
});

test("外接矩形の右辺が、90 度回った親の外接矩形の右辺に近づくと、親の座標で y が 0 の位置へ寄る", () => {
  /*
   * 外接矩形の右辺は 340 + 8 = 348 で、`frame` の右辺 350 へ 2 寄る。画面上で右へ 10 運んだ
   * ことになり、親の向きへ戻すと y が 10 減る
   */
  const onRepositionNode = vi.fn();
  renderCanvas({ selection: setupTurnedFrame(90), onRepositionNode });
  drawnTurnedFrame();

  dragNode("chip", { x: 8, y: 0 });

  expect(onRepositionNode).toHaveBeenCalledWith("chip", {
    parentName: "frame",
    placement: { mode: "absolute", x: 10, y: 0 },
  });
});

test("⌘ / Ctrl を押しながら 90 度回った親の中で同じ量運ぶと寄らず、親の座標で y が運んだ量だけ減る", () => {
  // 上のテストの対照。寄せ量が無ければ y は 10 - 8
  const onRepositionNode = vi.fn();
  renderCanvas({ selection: setupTurnedFrame(90), onRepositionNode });
  drawnTurnedFrame();

  dragNode("chip", { x: 8, y: 0 }, "ctrl");

  expect(onRepositionNode).toHaveBeenCalledWith("chip", {
    parentName: "frame",
    placement: { mode: "absolute", x: 10, y: 2 },
  });
});

test("90 度回った Box の中の回っていない Box の中のノードも、祖先の向きで親の座標へ戻される", () => {
  // 親の向きを自分の `rotation` から引くと、回っていない `inset` の 0 度になる
  const onRepositionNode = vi.fn();
  renderCanvas({ selection: setupTurnedFrame(90, true), onRepositionNode });
  drawnTurnedFrame(true);

  dragNode("dot", { x: -7, y: 0 });

  expect(onRepositionNode).toHaveBeenCalledWith("dot", {
    parentName: "inset",
    placement: { mode: "absolute", x: 10, y: 17 },
  });
});

test("90 度回った Box の中から回っていない親へ付け替えると、座標が指す点が画面上で同じ位置のまま新しい親の座標が書かれる", () => {
  /*
   * `frame` の座標の原点（回って描かれた左上の角）は `home` の座標で (250, 0)。運んだ先
   * (10, 17) を `home` の向きへ回すと (-17, 10) で、原点の位置を足して (233, 10)
   */
  const onRepositionNode = vi.fn();
  renderCanvas({ selection: setupTurnedFrame(90), onRepositionNode });
  drawnTurnedFrame();

  dragNodeOnto("chip", drawn("home"), { x: -7, y: 0 });

  expect(onRepositionNode).toHaveBeenCalledWith("chip", {
    parentName: "home",
    placement: { mode: "absolute", x: 233, y: 10 },
  });
});

test("回っていない親から 90 度回った Box へ付け替えると、同じ規則で回った親の座標が書かれる", () => {
  /*
   * `home` の座標の原点は `frame` の座標で (0, 250)。運んだ先 (200, 30) を `frame` の向きへ
   * 戻すと (30, -200) で、原点の位置を足して (30, 50)
   */
  const onRepositionNode = vi.fn();
  renderCanvas({ selection: setupTurnedFrame(90), onRepositionNode });
  drawnTurnedFrame();

  dragNodeOnto("pin", drawn("frame"), { x: 180, y: -120 });

  expect(onRepositionNode).toHaveBeenCalledWith("pin", {
    parentName: "frame",
    placement: { mode: "absolute", x: 30, y: 50 },
  });
});

test("倍率を上げても、90 度回った親の中の寄せ量が親の座標へ戻される", () => {
  /*
   * 1.2 倍では `chip` の外接矩形の右辺が 388 + 9 = 397 に来て、`frame` の右辺 400 へ 3 寄る。
   * 画面上で右へ 12 運んだことになり、倍率で割り戻して親の向きへ戻すと y が 10 減る
   */
  const onRepositionNode = vi.fn();
  renderCanvas({ selection: setupTurnedFrame(90), onRepositionNode });
  wheel(canvasSurface(), { x: 0, y: -100 }, "ctrl");
  drawnAt("home", { left: 100, top: 60, width: 432, height: 288 });
  drawnTurnedAt(
    "frame",
    { left: 280, top: 60, width: 120, height: 240 },
    { width: 200, height: 100 },
  );
  drawnTurnedAt(
    "chip",
    { left: 373.6, top: 72, width: 14.4, height: 24 },
    { width: 20, height: 12 },
  );

  dragNode("chip", { x: 9, y: 0 });

  expect(onRepositionNode).toHaveBeenCalledWith("chip", {
    parentName: "frame",
    placement: { mode: "absolute", x: 10, y: 0 },
  });
});

test("360 度回った Box の中のノードは、回っていない Box の中と同じ座標が書かれる", () => {
  const onRepositionNode = vi.fn();
  renderCanvas({ selection: setupTurnedFrame(360), onRepositionNode });
  drawnUprightFrame();

  dragNode("chip", { x: 12, y: 5 });

  expect(onRepositionNode).toHaveBeenCalledWith("chip", {
    parentName: "frame",
    placement: { mode: "absolute", x: 22, y: 15 },
  });
});

test("90 度回った親の中で画面上の左へ運ぶと、書かれる座標は親の座標で y が運んだ量だけ増える", () => {
  // 運んだ量を親の向きへ戻さないと x が 7 減る
  const dropped = RepositionTarget.create(
    GrabbedInTurned,
    { x: -7, y: 0 },
    Turned,
  );

  expect(dropped.to).toEqual({
    parentName: "frame",
    placement: { mode: "absolute", x: 40, y: 31 },
  });
});

test("90 度回った親の中で画面上の左へ運ぶと、見た目のずらし量も親の向きへ戻した量になる", () => {
  // ずらし量は親と一緒に回って効くので、戻さないと画面上では上へずれて見える
  const dropped = RepositionTarget.create(
    GrabbedInTurned,
    { x: -7, y: 0 },
    Turned,
  );

  expect(dropped.offset).toEqual({ x: 0, y: 7 });
});

test("90 度回った親の中で、親を決めずに求めたずらし量も親の向きへ戻した量になる", () => {
  // 落とせる場所の外へ出た瞬間にずれる向きが変わってはいけないので、`create` と同じ戻し方
  expect(
    RepositionTarget.carriedOffset(GrabbedInTurned, { x: -7, y: 0 }),
  ).toEqual({ x: 0, y: 7 });
});

test("30 度回った親の中で割り切れない量を運んでも、書かれる座標とずらし量は同じ丸めた行き先から出る", () => {
  // 親の向きへ戻した量は (19.12, -23.54)。丸めた行き先 (59, 0) から逆算すると (19, -24)
  const dropped = RepositionTarget.create(
    { placement: GrabbedAt, parentRotation: 30 },
    { x: 28.33, y: -10.83 },
    { name: "home", shift: { x: 0, y: 0 }, rotation: 30 },
  );

  expect([dropped.to.placement, dropped.offset]).toEqual([
    { mode: "absolute", x: 59, y: 0 },
    { x: 19, y: -24 },
  ]);
});

test("90 度回った親から回っていない親へ付け替えると、書かれる座標は親の座標の原点と向きを直した値になる", () => {
  /*
   * 今の親の座標の原点は、落とし先の座標で (250, 0)。運んだ先 (10, 17) を 90 度回すと
   * (-17, 10) で、原点の位置を足して (233, 10)。向きを直さないと (260, 17) になる
   */
  const dropped = RepositionTarget.create(
    { placement: { mode: "absolute", x: 10, y: 10 }, parentRotation: 90 },
    { x: -7, y: 0 },
    { name: "home", shift: { x: 250, y: 0 }, rotation: 0 },
  );

  expect(dropped.to).toEqual({
    parentName: "home",
    placement: { mode: "absolute", x: 233, y: 10 },
  });
});

test("回っていない親から 90 度回った親へ付け替えると、書かれる座標は落とし先の向きで測った値になる", () => {
  /*
   * 今の親の座標の原点は、落とし先の座標で (0, 250)。運んだ先 (200, 30) を -90 度回すと
   * (30, -200) で、原点の位置を足して (30, 50)。向きを直さないと (200, 280) になる
   */
  const dropped = RepositionTarget.create(
    { placement: { mode: "absolute", x: 20, y: 150 }, parentRotation: 0 },
    { x: 180, y: -120 },
    { name: "frame", shift: { x: 0, y: 250 }, rotation: 90 },
  );

  expect(dropped.to).toEqual({
    parentName: "frame",
    placement: { mode: "absolute", x: 30, y: 50 },
  });
});

test("360 度回った親の中では、回っていない親の中と同じ座標が書かれる", () => {
  const dropped = RepositionTarget.create(
    { placement: GrabbedAt, parentRotation: 360 },
    { x: 30, y: -12 },
    { name: "home", shift: { x: 0, y: 0 }, rotation: 360 },
  );

  expect(dropped.to).toEqual({
    parentName: "home",
    placement: { mode: "absolute", x: 70, y: 12 },
  });
});

test("回っていない親の中の位置へ置き直すと、回る前の矩形の左上がその位置に来て大きさと向きは変わらない", () => {
  const placed = RotatedBounds.placedAt(
    { unrotated: Unrotated, rotation: 30 },
    {
      unrotated: { left: 10, top: 20, width: 400, height: 300 },
      rotation: 0,
    },
    { x: 5, y: 7 },
  );

  expect(placed).toEqual({
    unrotated: { left: 15, top: 27, width: 200, height: 100 },
    rotation: 30,
  });
});

test("90 度回った親の中の位置へ置き直すと、親と一緒に回った位置に中心が来る", () => {
  // 回る前の位置 (210, 120) の中心 (220, 126) を、親の中心 (300, 160) まわりに 90 度回す
  const placed = RotatedBounds.placedAt(
    { unrotated: { left: 0, top: 0, width: 20, height: 12 }, rotation: 90 },
    TurnedParent,
    { x: 10, y: 10 },
  );

  expect(placed).toEqual({
    unrotated: { left: 324, top: 74, width: 20, height: 12 },
    rotation: 90,
  });
});

test("どちらも回っていなければ、原点にする矩形の座標で見た位置は左上どうしの差になる", () => {
  // 縦横で符号を違える（取り違えても片方だけでは落ちないため）
  const shift = RotatedBounds.originShift(
    { unrotated: Unrotated, rotation: 0 },
    { unrotated: { left: 120, top: 35, width: 200, height: 80 }, rotation: 0 },
  );

  expect(shift).toEqual({ x: -20, y: 15 });
});

test("90 度回った矩形の回る前の左上の角を、回っていない矩形の座標で見ると、回って描かれた角の位置になる", () => {
  // 角は回って (350, 60) に描かれる。回る前の左上 (200, 110) を使うと (100, 50) になる
  expect(RotatedBounds.originShift(TurnedParent, Upright)).toEqual({
    x: 250,
    y: 0,
  });
});

test("回っていない矩形の左上を 90 度回った矩形の座標で見ると、その向きで測った位置になる", () => {
  // 原点からの画面上の差 (-100, -50) を、向きを戻して測る。戻さないと (-100, -50) のまま
  const shift = RotatedBounds.originShift(Upright, TurnedParent);

  expect(shift).toEqual({ x: 0, y: 250 });
});

create(
  from: GrabbedPlacement,
  carried: Offset,
  dropParent: DropParentCoordinates,
): RepositionTarget {
  const moved = movedInParent(from, carried);
  const point = Placement.offset(moved);
  const turned = Offset.rotate(
    point,
    from.parentRotation - dropParent.rotation,
  );
  return {
    to: ChildPlacement.create(
      dropParent.name,
      Placement.moveBy(
        moved,
        Offset.add(Offset.delta(point, turned), dropParent.shift),
      ),
    ),
    offset: offsetToward(from, moved),
  };
},

originShift(bounds: RotatedBounds, origin: RotatedBounds): Offset {
  return Offset.delta(
    CanvasBounds.pointAt(origin.unrotated, { x: 0, y: 0 }),
    RotatedBounds.unrotatePoint(
      origin,
      RotatedBounds.pointAt(bounds, { x: 0, y: 0 }),
    ),
  );
},
